def evaluate(expr: str) -> int:
    def apply_op(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            # Integer division truncating toward zero
            if left * right < 0 and left % right != 0:
                values.append(left // right + 1)
            else:
                values.append(left // right)

    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    values = []
    operators = []
    i = 0
    n = len(expr)

    while i < n:
        if expr[i] == ' ':
            i += 1
            continue

        if expr[i].isdigit():
            val = 0
            while i < n and expr[i].isdigit():
                val = val * 10 + int(expr[i])
                i += 1
            values.append(val)
            continue

        if expr[i] == '(':
            operators.append('(')
        elif expr[i] == ')':
            while operators and operators[-1] != '(':
                apply_op(operators, values)
            operators.pop()  # Pop '('
        else:
            # Current char is an operator
            while (operators and operators[-1] != '(' and 
                   precedence[operators[-1]] >= precedence[expr[i]]):
                apply_op(operators, values)
            operators.append(expr[i])
        i += 1

    while operators:
        apply_op(operators, values)

    return values[0]
