    def _flatten(current_obj, parent_key=""):
        items = {}

        # Handle empty dict or empty list as leaf nodes
        if isinstance(current_obj, dict) and not current_obj:
            return {parent_key: {}}
        if isinstance(current_obj, list) and not current_obj:
            return {parent_key: []}

        # Determine the iterator based on type
        if isinstance(current_obj, dict):
            iterator = current_obj.items()
        elif isinstance(current_obj, list):
            iterator = enumerate(current_obj)
        else:
            # This case shouldn't be reached by the recursive logic for non-leaves
            return {parent_key: current_obj}

        for k, v in iterator:
            new_key = f"{parent_key}.{k}" if parent_key else str(k)

            if isinstance(v, (dict, list)) and v:
                # If it's a non-empty dict or list, recurse
                # Special check: if it's a list, we use index as key
                # If it's a dict, we use the key
                res = _flatten(v, new_key)
                items.update(res)
            else:
                # It's a leaf (primitive or empty container)
                items[new_key] = v

        return items

